<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import de from '../../i18n/de'
import { useForm, router } from '@inertiajs/vue3'
import { ref } from 'vue'
import { computed } from 'vue'
const props = defineProps({ group: Object, plan: Object, unitTemplates: Array })
const open = ref(false)
const form = useForm({ title: '', starts_on: props.group.school_year.starts_on, ends_on: props.group.school_year.starts_on, planned_hours: 1, unit_template_id: '', is_interrupted: false, notes: '' })
function save() { form.post(`/jahresplanung/${props.group.id}/einheiten`, { onSuccess: () => { open.value = false; form.reset() } }) }
function generate() { router.post(`/jahresplanung/${props.group.id}/stunden-erzeugen`) }
function remove(unit) { if (window.confirm('Diese Unterrichtseinheit aus der Planung entfernen?')) useForm({}).delete(`/jahresplanung/${props.group.id}/einheiten/${unit.id}`) }
function updateStatus(occurrence, status) { useForm({ status, actual_on: occurrence.actual_on, notes: occurrence.notes }).put(`/jahresplanung/${props.group.id}/vorkommnisse/${occurrence.id}`) }
function moveUnit(unit, days) { const shift = (value) => { const date = new Date(`${value}T12:00:00`); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10) }; useForm({ title: unit.title, starts_on: shift(unit.starts_on), ends_on: shift(unit.ends_on), planned_hours: unit.planned_hours, unit_template_id: unit.unit_template_id, curriculum_topic_id: unit.curriculum_topic_id, is_interrupted: unit.is_interrupted, notes: unit.notes ?? '' }).put(`/jahresplanung/${props.group.id}/einheiten/${unit.id}`) }
function splitUnit(unit) { const splitOn = window.prompt(`${de.splitUnit}: Datum (JJJJ-MM-TT)`, unit.starts_on); if (splitOn) useForm({ split_on: splitOn }).post(`/jahresplanung/${props.group.id}/einheiten/${unit.id}/teilen`) }
const weeks = computed(() => { const result = []; const start = new Date(`${props.group.school_year.starts_on}T12:00:00`); const end = new Date(`${props.group.school_year.ends_on}T12:00:00`); start.setDate(start.getDate() - ((start.getDay() + 6) % 7)); for (let date = start; date <= end; date.setDate(date.getDate() + 7)) result.push(new Date(date)); return result })
function timelineStyle(unit) { const start = new Date(`${props.group.school_year.starts_on}T12:00:00`); const end = new Date(`${props.group.school_year.ends_on}T12:00:00`); const total = Math.max(1, (end - start) / 86400000); const left = Math.max(0, (new Date(`${unit.starts_on}T12:00:00`) - start) / 86400000 / total * 100); const width = Math.max(3, ((new Date(`${unit.ends_on}T12:00:00`) - new Date(`${unit.starts_on}T12:00:00`)) / 86400000 + 1) / total * 100); return { left: `${left}%`, width: `${width}%` } }
</script>
<template>
    <AppShell><template #toolbar><a href="/jahresplanung" class="btn btn-sm btn-light" :title="de.close" :aria-label="de.close"><i class="bi bi-x-lg" aria-hidden="true"></i></a><button class="btn btn-sm btn-outline-primary" type="button" @click="generate">{{ de.generateLessons }}</button></template>
        <div class="container-full px-3 py-4"><h1 class="h2">{{ de.yearPlans }}: {{ group.name }}</h1><p class="text-muted">{{ group.school.name }} · {{ group.school_year.name }} · {{ group.school_year.starts_on }} – {{ group.school_year.ends_on }}</p><div v-if="$page.props.flash?.success" class="alert alert-success">{{ $page.props.flash.success }}</div>
            <section class="card card-body mb-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.plannedUnits }}</h2><button class="btn btn-sm btn-outline-primary" type="button" @click="open = true">{{ de.addPlannedUnit }}</button></div><div class="roo-plan-timeline mb-3" role="img" :aria-label="de.plannedUnits"><span v-for="week in weeks" :key="week.toISOString()" class="roo-plan-week" :style="{ left: `${Math.max(0, ((week - new Date(`${group.school_year.starts_on}T12:00:00`)) / 86400000) / Math.max(1, (new Date(`${group.school_year.ends_on}T12:00:00`) - new Date(`${group.school_year.starts_on}T12:00:00`)) / 86400000) * 100)}%` }">{{ week.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' }) }}</span><span v-for="unit in plan.units" :key="`timeline-${unit.id}`" class="roo-plan-unit" :style="timelineStyle(unit)">{{ unit.title }}</span></div><div v-if="!plan.units.length" class="text-muted">{{ de.noPlannedUnits }}</div><div v-for="unit in plan.units" :key="unit.id" class="border rounded p-3 mb-2"><div class="d-flex justify-content-between"><div><strong>{{ unit.title }}</strong><div class="small text-muted">{{ unit.starts_on }} – {{ unit.ends_on }} · {{ unit.planned_hours }} {{ de.hours.toLowerCase() }}<span v-if="unit.template"> · {{ unit.template.title }}</span></div></div><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.moveEarlier" :aria-label="de.moveEarlier" @click="moveUnit(unit, -7)"><i class="bi bi-arrow-left" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.moveLater" :aria-label="de.moveLater" @click="moveUnit(unit, 7)"><i class="bi bi-arrow-right" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.splitUnit" :aria-label="de.splitUnit" @click="splitUnit(unit)"><i class="bi bi-scissors" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-danger" type="button" @click="remove(unit)"><i class="bi bi-trash" aria-hidden="true"></i></button></div></div><div v-if="unit.lessons?.length" class="mt-3"><div class="small fw-semibold mb-1">{{ de.lessonOccurrences }}</div><div v-for="lesson in unit.lessons" :key="lesson.id"><div v-for="occurrence in lesson.occurrences" :key="occurrence.id" class="d-flex align-items-center gap-2 mb-1"><span class="small">{{ occurrence.planned_on }} · {{ lesson.title }}</span><select class="form-select form-select-sm w-auto" :value="occurrence.status" @change="updateStatus(occurrence, $event.target.value)"><option v-for="(label, value) in de.statusLabels" :key="value" :value="value">{{ label }}</option></select></div></div></div></div></section>
            <section class="card card-body mb-4"><h2 class="h5">{{ de.planningChecks }}</h2><div class="row g-2 small"><div class="col-sm-3"><strong>{{ de.availableHours }}</strong><br>{{ checks.available_hours }}</div><div class="col-sm-3"><strong>{{ de.plannedCompetenceCount }}</strong><br>{{ checks.planned_competence_count }}</div><div class="col-sm-3"><strong>{{ de.unitsWithoutCompetencies }}</strong><br>{{ checks.units_without_competencies.length ? checks.units_without_competencies.join(', ') : 'Keine' }}</div><div class="col-sm-3"><strong>{{ de.topicsWithoutPlannedUnit }}</strong><br>{{ checks.topics_without_planned_unit.length ? checks.topics_without_planned_unit.join(', ') : 'Keine' }}</div></div></section>
            <section v-if="plan.revisions?.length" class="card card-body"><h2 class="h5">{{ de.planHistory }}</h2><div v-for="revision in plan.revisions" :key="revision.id" class="small border-bottom py-2">{{ revision.created_at }} · {{ revision.description }}</div></section>
        </div>
        <div v-if="open" class="roo-modal-backdrop" role="presentation" @click.self="open = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.addPlannedUnit"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.addPlannedUnit }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="open = false"></button></div><form @submit.prevent="save"><label class="form-label">{{ de.unitTitle }}</label><input v-model="form.title" class="form-control" required><label class="form-label mt-2">{{ de.planTemplate }}</label><select v-model="form.unit_template_id" class="form-select"><option value="">–</option><option v-for="template in unitTemplates" :key="template.id" :value="template.id">{{ template.title }}</option></select><div class="row g-2 mt-1"><div class="col-6"><label class="form-label">{{ de.planStart }}</label><input v-model="form.starts_on" type="date" class="form-control" required></div><div class="col-6"><label class="form-label">{{ de.planEnd }}</label><input v-model="form.ends_on" type="date" class="form-control" required></div></div><label class="form-label mt-2">{{ de.plannedHours }}</label><input v-model="form.planned_hours" type="number" min="1" class="form-control" required><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="open = false">{{ de.cancel }}</button><button class="btn btn-primary" type="submit">{{ de.save }}</button></div></form></div></div></section></div>
    </AppShell>
</template>
